WITH deduped AS (SELECT * FROM customers QUALIFY ROW_NUMBER() OVER (PARTITION BY country, segment ORDER BY age DESC NULLS LAST, id) = 1), not_flagged AS (SELECT s.* FROM deduped s WHERE EXISTS (SELECT 1 FROM orders x WHERE x.customer_id = s.id AND x.order_date < s.signup_date)), valid AS (SELECT *, ROUND(credit_limit * 0.85, 2) AS credit_limit_scaled, WEEKOFYEAR(signup_date) AS signup_date_weekofyear FROM not_flagged WHERE signup_date > DATE '2023-06-23' AND city IS DISTINCT FROM 'London'), deduped_customers AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, segment ORDER BY credit_limit_scaled DESC NULLS LAST, id) AS dedup_rank FROM valid QUALIFY dedup_rank = 1), kept AS (SELECT s.* FROM deduped_customers s WHERE NOT EXISTS (SELECT 1 FROM sessions x WHERE x.customer_id = s.id AND x.started_at < '2023-10-30')) SELECT *, LAST_VALUE(credit_limit) IGNORE NULLS OVER (PARTITION BY segment ORDER BY credit_limit_scaled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_credit_limit, ROW_NUMBER() OVER (PARTITION BY MONTH(signup_date), country ORDER BY credit_limit DESC, id) AS row_seq, NTILE(10) OVER (PARTITION BY city ORDER BY credit_limit DESC, id) AS credit_limit_bucket FROM kept WHERE is_active
